/* Thin C wrapper around the code generated by Treelite/TL2cgen (header.h + main.c + tu*.c).
 * Compiled once per forest (gaze, hand) with  -DFOREST_PREFIX=gaze_  /  -DFOREST_PREFIX=hand_  (see CMakeLists.txt).
 * tools/export_forests.py has already renamed every global symbol of the generated code with the same prefix
 * (gaze_predict, hand_predict, ...), so two forests can live in one executable without clashing.
 *
 * Exports (with the prefix):  <p>forest_num_features, <p>forest_num_classes,
 *                             <p>forest_predict   (argmax class; ties -> lowest label, like numpy.argmax)
 *                             <p>forest_proba     (the averaged class probabilities = scikit-learn predict_proba)
 * Input features are float32, exactly like scikit-learn rounds them before walking its trees. */
#include <stdint.h>
#include "header.h"

#ifndef FOREST_PREFIX
#error "compile with -DFOREST_PREFIX=gaze_ (or hand_)"
#endif
#define SHIM_CAT2(a, b) a##b
#define SHIM_CAT(a, b) SHIM_CAT2(a, b)
#define P(name) SHIM_CAT(FOREST_PREFIX, name)

#define SHIM_MAX_FEATURES 64

int P(forest_num_features)(void) { return (int)P(get_num_feature)(); }

int P(forest_num_classes)(void) {
    int32_t n[8];
    n[0] = 0;
    P(get_num_class)(n);
    return (int)n[0];
}

/* Writes the class probabilities to out[0..n-1] and returns n (0 on error). */
int P(forest_proba)(const float* features, double* out, int max_out) {
    union Entry e[SHIM_MAX_FEATURES];
    double res[MAX_N_CLASS];
    int nf = (int)P(get_num_feature)();
    int nc = P(forest_num_classes)();
    int i;
    if (nf > SHIM_MAX_FEATURES || nc > MAX_N_CLASS || nc < 1 || nc > max_out) return 0;
    for (i = 0; i < nf; ++i) e[i].fvalue = features[i];
    for (i = 0; i < nc; ++i) res[i] = 0.0;
    P(predict)(e, 0, res);
    for (i = 0; i < nc; ++i) out[i] = res[i];
    return nc;
}

int P(forest_predict)(const float* features) {
    double p[MAX_N_CLASS];
    int n = P(forest_proba)(features, p, MAX_N_CLASS);
    int i, best = 0;
    for (i = 1; i < n; ++i)
        if (p[i] > p[best]) best = i;
    return best;
}
